      "criterion": "parseGitCredentials() rejects arrays with duplicate id values.",
      "met": true
    },
    {
      "criterion": "parseGitCredentials() rejects entries with empty id, label, host, or token fields.",
      "met": true
    },
    {
      "criterion": "When two old-format entries would produce the same kebab-case ID, a numeric suffix is appended to disambiguate.",
      "met": true
    },
    {
      "criterion": "config.dist.json contains \"gitCredentials\": [].",
      "met": true
    },
    {
      "criterion": "All unit tests in src/tests/config.test.ts for migration and validation pass.",
      "met": true
    }
  ],
  "active_pipeline_stages": [
