  1	import { chmodSync } from 'node:fs';
  2	import { getConfigPath } from '../utils/paths.js';
  3	import { readJsonFile, writeJsonFile, FileNotFoundError } from '../storage/json-storage.js';
  4	import type { AppConfig, GitCredentialEntry } from './config.types.js';
  5	import { toKebabCase } from '../utils/slug.js';
  6	import {
  7	    DEFAULT_NOTES_CARD_HEIGHT,
  8	    DEFAULT_NOTES_COLUMNS,
  9	    MIN_NOTES_CARD_HEIGHT,
 10	    MAX_NOTES_CARD_HEIGHT,
 11	    MIN_NOTES_COLUMNS,
 12	    MAX_NOTES_COLUMNS,
 13	    MIN_POLLING_INTERVAL_SECONDS,
 14	    MAX_POLLING_INTERVAL_SECONDS,
 15	    MIN_CLONE_DEPTH,
 16	    MAX_CLONE_DEPTH,
 17	    MIN_SERVER_PORT,
 18	    MAX_SERVER_PORT,
 19	} from './config.constants.js';
 20	
 21	const REQUIRED_FIELDS: ReadonlyArray<keyof AppConfig> = ['projectsFolder', 'storageFolder'];
 22	
 23	// When adding a new non-optional AppConfig field with a sensible default: add the
 24	// key to the Pick<AppConfig, ...> union and its value here, then update loadConfig()
 25	// to fall back to it. The satisfies guard below will catch if DEFAULTS is incomplete.
 26	export const DEFAULTS: Readonly<Pick<AppConfig, 'cloneDepth' | 'serverPort' | 'gitPollingIntervalSeconds' | 'notesCardHeight' | 'notesColumns'>> = {
 27	    cloneDepth: 50,
 28	    serverPort: 4200,
 29	    gitPollingIntervalSeconds: 30,
 30	    notesCardHeight: DEFAULT_NOTES_CARD_HEIGHT,
 31	    notesColumns: DEFAULT_NOTES_COLUMNS,
 32	};
 33	
 34	// Compile-time guard: ensures DEFAULTS + required fields cover the full AppConfig shape.
 35	// If a new required field is added to AppConfig without updating DEFAULTS, this line
 36	// will produce a type error.
 37	const _defaultsCoverageGuard: AppConfig = {
 38	    ...DEFAULTS,
 39	    projectsFolder: '',
 40	    storageFolder: '',
