 44	/**
 45	 * Loads, validates, and returns the application configuration from `config.json`.
 46	 *
 47	 * **Setup:** Copy `config.dist.json` to `config.json` and fill in the required
 48	 * fields before running the tool.
 49	 *
 50	 * @param configPath Optional absolute path to the config file. Defaults to the
 51	 *   `config.json` in the tool root. Pass a custom path in tests to avoid touching
 52	 *   the real config file.
 53	 * @throws {Error} If `config.json` does not exist (with instruction to copy from
 54	 *   `config.dist.json`).
 55	 * @throws {Error} If any required field is missing, non-string, or empty.
 56	 */
 57	export function loadConfig(configPath?: string): AppConfig {
 58	    const resolvedConfigPath = configPath ?? getConfigPath();
 59	    let raw: Record<string, unknown>;
 60	
 61	    try {
 62	        raw = readJsonFile<Record<string, unknown>>(resolvedConfigPath);
 63	    } catch (err) {
 64	        if (err instanceof FileNotFoundError) {
 65	            throw new Error(
 66	                `config.json not found at "${resolvedConfigPath}". ` +
 67	                `Copy config.dist.json to config.json and fill in the required fields.`
 68	            );
 69	        }
 70	        throw err;
 71	    }
 72	
 73	    for (const field of REQUIRED_FIELDS) {
 74	        const value = raw[field];
 75	        if (typeof value !== 'string' || value.trim() === '') {
 76	            throw new Error(
 77	                `Configuration error: required field "${field}" must be a non-empty string in config.json.`
 78	            );
 79	        }
 80	    }
 81	
 82	    return {
 83	        projectsFolder: raw['projectsFolder'] as string,
 84	        storageFolder: raw['storageFolder'] as string,
 85	        cloneDepth: parseIntegerField(raw['cloneDepth'], 'cloneDepth', DEFAULTS.cloneDepth, MIN_CLONE_DEPTH, MAX_CLONE_DEPTH),
 86	        serverPort: parseIntegerField(raw['serverPort'], 'serverPort', DEFAULTS.serverPort, MIN_SERVER_PORT, MAX_SERVER_PORT),
 87	        gitPollingIntervalSeconds: parseIntegerField(
 88	            raw['gitPollingIntervalSeconds'],
 89	            'gitPollingIntervalSeconds',
 90	            DEFAULTS.gitPollingIntervalSeconds,
 91	            MIN_POLLING_INTERVAL_SECONDS,
 92	            MAX_POLLING_INTERVAL_SECONDS,
 93	        ),
 94	        gitCredentials: parseGitCredentials(raw['gitCredentials']),
 95	        webserverUrl: typeof raw['webserverUrl'] === 'string' && raw['webserverUrl'].trim() !== ''
 96	            ? raw['webserverUrl'].trim().replace(/\/+$/, '')
 97	            : undefined,
 98	        notesCardHeight: parseIntegerField(
 99	            raw['notesCardHeight'],
100	            'notesCardHeight',

101	            DEFAULTS.notesCardHeight,
102	            MIN_NOTES_CARD_HEIGHT,
103	            MAX_NOTES_CARD_HEIGHT,
104	        ),
105	        notesColumns: parseIntegerField(
106	            raw['notesColumns'],
107	            'notesColumns',
108	            DEFAULTS.notesColumns,
109	            MIN_NOTES_COLUMNS,
110	            MAX_NOTES_COLUMNS,
111	        ),
112	    };
113	}
