271	/**
272	 * Reads `config.json`, sets or removes a single top-level field, and writes the
273	 * file back via `writeJsonFile()`. All other fields — including `_instructions`
274	 * — are preserved.
275	 *
276	 * @param field - The top-level key to modify (e.g. `"gitCredentials"`).
277	 * @param value - The value to set, or `undefined` to remove the field.
278	 * @param configPath - Optional absolute path to the config file. Defaults to
279	 *   the tool-root `config.json`.
280	 * @throws {Error} If `config.json` cannot be read or written.
281	 */
282	export function saveConfigField(
283	    field: string,
284	    value: unknown,
285	    configPath?: string,
286	): void {
287	    const resolvedConfigPath = configPath ?? getConfigPath();
288	    const raw = readJsonFile<Record<string, unknown>>(resolvedConfigPath);
289	
290	    if (value === undefined) {
291	        delete raw[field];
292	    } else {
293	        raw[field] = value;
294	    }
295	
296	    writeJsonFile(resolvedConfigPath, raw);
297	
298	    // config.json may contain plaintext PATs in gitCredentials — restrict
299	    // file permissions to owner-only on POSIX systems.
300	    if (process.platform !== 'win32') {
301	        chmodSync(resolvedConfigPath, 0o600);
302	    }
303	}

