 17	/**
 18	 * Installs a `console.warn` spy, runs `fn`, restores the original, and returns
 19	 * all captured warning strings (each joined from all arguments with a space).
 20	 */
 21	function captureWarnings<T>(fn: () => T): { result: T; warnings: string[] } {
 22	    const warnings: string[] = [];
 23	    const originalWarn = console.warn;
 24	    console.warn = (...args: unknown[]) => { warnings.push(args.map(String).join(' ')); };
 25	    try {
 26	        const result = fn();
 27	        return { result, warnings };
 28	    } finally {
 29	        console.warn = originalWarn;
 30	    }
 31	}
